export const FOX_PLAYER_BIOS: FoxPlayerBioEntry[] = [
  { name: "Alexis Mac Allister", team: "Argentina", source: "top100", bio: "Mac Allister will be a key presence in the Argentina midfield this summer, as he was in 2022 en route to World Cup glory. Since then, he moved to Liverpool and won the Premier League last season. Mac Allister is capable of popping up and scoring a huge goal while also dictating the game on the ball. He’s one of the best center midfielders in the world." },
  { name: "Emiliano Martínez", team: "Argentina", source: "top100", bio: "Martínez burst onto the scene in 2020 for Arsenal, and his ascension has seemingly never stopped. He quickly became Argentina’s starting goalkeeper, and then he was the hero in the 2022 World Cup final in the penalty shootout. Martínez is among the best goalkeepers in the world and brings an attitude to the game that has the spotlight constantly on him." },
  { name: "Enzo Fernández", team: "Argentina", source: "top100", bio: "Fernández broke out during Argentina’s run to World Cup glory in 2022 and made a move to Chelsea one month after lifting the trophy. He’s an all-action midfielder who can cover every blade of grass and is capable of popping up with a big goal when necessary. He’ll be the key man in Argentina’s midfield this summer." },
  { name: "Julián Álvarez", team: "Argentina", source: "top100", bio: "Álvarez’s coming-out party was during the 2024 World Cup, when he was a key piece in Argentina’s attack en route to the title. After two seasons at Manchester City, Álvarez moved to Atlético Madrid, where he has played more of a starring role as a center forward. Technically quick with his feet, Álvarez’s work rate is impressive for a striker. After years of looking for the ideal strike partner next to Messi, Álvarez has emerged as the ideal player to go alongside the all-time great. He’ll play a crucial part in Argentina’s title defense." },
  { name: "Lautaro Martínez", team: "Argentina", source: "top100", bio: "Martínez has scored more than 200 goals between Inter Milan and the national team since moving to Italy in 2018. He has firmly established himself as one of the best and most consistent strikers in the world, having scored at least 20 goals in each of the last five seasons. Whether Martínez starts for Argentina remains to be seen, with Julián Álvarez also thriving alongside Lionel Messi." },
  { name: "Lionel Messi", team: "Argentina", source: "top100", bio: "Maybe the best player of all time, Messi will turn 39 years old on June 24. He is still extremely capable of leading the reigning world champions to a repeat run at the title. Messi has spent the past three seasons in MLS and is still averaging well north of 1.5 goals/assists per game for Inter Miami. Messi has made a staggering 198 appearances (second most among players likely to appear at the tournament) for Argentina with 116 goals to his name. As long as he is on the field, he will be the go-to guy for Argentines, who will go as far in the tournament as he takes them." },
  { name: "Lisandro Martínez", team: "Argentina", source: "top100", bio: "Martínez would start at center back for most teams in this tournament, but he’s likely going to start as the third option behind Cristian Romero and Nicolas Otamendi, who started during Argentina’s winning run in 2022. He can fill in at left back, as well, and will play a role somehow for the reigning champions." },
  { name: "Jérémy Doku", team: "Belgium", source: "top100", bio: "Doku is a defender’s nightmare when he is on his game. The Belgian winger might be the best dribbler in the World Cup. He’s smooth on the ball and has impressive pace and quickness that will wreak havoc in the opposition’s 18-yard box. With midfielder Kevin De Bruyne and striker Romelu Lukaku getting up there in years, Doku looks like the future of the Belgium team." },
  { name: "Kevin De Bruyne", team: "Belgium", source: "top100", bio: "While De Bruyne is getting older, class is permanent. At 34 years old, he is still one of the best playmakers in world soccer. The key for him is to make sure he stays healthy so he can add to his 117 national-team appearances and 36 goals. If Belgium has success this summer, it will go through its midfield maestro." },
  { name: "Thibaut Courtois", team: "Belgium", source: "top100", bio: "Over the past decade, he has been the best goalkeeper in the world. At 6-foot-7, it’s very difficult to beat Courtois, who has put in match-winning performances on the biggest stages at Real Madrid. His performance at the 2022 Champions League Final in Real’s 1-0 win over Liverpool was the stuff of legend. Belgium has a big leg up with Courtois between the posts." },
  { name: "Alisson", team: "Brazil", source: "top100", bio: "Part of what makes Alisson one of the best goalkeepers in the world is his ability with his feet. He may be the best passer at his position in world soccer. His problem in past years has been staying on the pitch, as he’s missed at least 10 Premier League games in each of the last three seasons. When he’s between the posts, though, he’s still one of the world’s best for both club and country." },
  { name: "Bruno Guimarães", team: "Brazil", source: "top100", bio: "Guimarães will be a big presence in midfield for Brazil. He’s capable of covering every blade of grass and has the kind of attitude that wins games." },
  { name: "Casemiro", team: "Brazil", source: "top100", bio: "Casemiro is a four-time Champions League winner at Real Madrid, but he hasn’t maintained his high level of quality since moving to Manchester United in 2022. His former Real Madrid manager, Carlo Ancelotti, is now in charge of Brazil and brought the midfielder back to the national team last year." },
  { name: "Gabriel Magalhães", team: "Brazil", source: "top100", bio: "Gabriel is the No. 1-ranked center back on this list, having established himself on both ends of the pitch for Arsenal in recent years. The Brazilian has made more than 220 appearances over the past five seasons for the Gunners, and he has established himself as a first-choice player for the national team. Gabriel has also made his name in attack as one of the best threats from corner and free kicks. The left-footed defender, though, will be a key cog as Brazil looks to return to glory this summer." },
  { name: "Gabriel Martinelli", team: "Brazil", source: "top100", bio: "Martinelli will be a key player for Brazil this summer. He has struggled to establish a starting spot on the left wing because of Vinícius Júnior and Rodrygo, but his pace means he will be a key contributor this summer. He only has one Premier League goal for Arsenal this season, so he isn’t in the best form right now." },
  { name: "João Pedro", team: "Brazil", source: "top100", bio: "Brazil has been looking for a definitive No. 9 in its lineup for years, and Pedro might be the answer. After two impressive seasons at Brighton, he has 14 Premier League goals for Chelsea this season. He’ll likely be the focal point of Brazil’s attack this summer, which puts a lot on his shoulders for the perennial contender." },
  { name: "Marquinhos", team: "Brazil", source: "top100", bio: "At 31 years old, Marquinhos has already played 104 times for his country. He has been widely considered one of the best defenders in the world for the past decade, having played more than 500 games for PSG since arriving in 2013. The 31-year-old is still playing at a high level and will be wearing the captain’s armband for Brazil this summer." },
  { name: "Raphinha", team: "Brazil", source: "top100", bio: "While Vinícius Júnior makes the headlines for Brazil, Raphinha will be just as important to any success that the Seleção will have this summer. He moved to Barcelona in 2022 after two seasons in the Premier League with Leeds United and has been a key man for the club since. His best moment was the 2024-25 season, when he registered 34 goals and 22 assists across 57 games. He has been injured for a large part of this season but is regaining fitness just in time to play a starring role for Brazil this summer. The left-footed winger will be a force to be reckoned with on the right wing." },
  { name: "Vinícius Júnior", team: "Brazil", source: "top100", bio: "Few players grab headlines like Vini Jr. The 25-year-old joined Real Madrid at 18 years old and has made more than 370 appearances for Los Blancos. He has won the Champions League twice, including scoring the winner in both finals in 2022 and 2024. For the national team, though, Vini has not reached the same heights he has with his club. He is yet to win a major trophy at the international level but will be front and center of Brazil’s efforts this season. Vini will start on the left wing and be a focal point for manager Carlo Ancelotti, who coached him to those Champions League triumphs in Ma" },
  { name: "Alphonso Davies", team: "Canada", source: "top100", bio: "Davies moved to Canada when he was 5 years old and became the face of Canadian soccer about 12 years later. He started his career in MLS with the Vancouver Whitecaps before moving to Bayern Munich in 2018. From there, he became the best attacking left back in the world with his impressive pace and physicality. For Canada, Davies plays a more attacking role. He will have to play well if the host nation is going to succeed this summer." },
  { name: "Luis Díaz", team: "Colombia", source: "top100", bio: "Díaz was already known as one of the best wingers in the world after four seasons at Liverpool, but he has gone to another level this season after moving to Bayern Munich. The Colombian winger is nonstop action when he’s on the pitch with a relentless motor and impressive pace that will create problems for any defense. While James Rodriguez is the big name for Colombia, Díaz will be the key player for it this summer." },
  { name: "Joško Gvardiol", team: "Croatia", source: "top100", bio: "Gvardiol is the most expensive defender in soccer history, having cost Manchester City $105 million back in 2023. He has been injured for much of this season, but he’s one of the best passing defenders in the world. While Luka Modrić runs the Croatian midfield, Gvardiol will command the defense." },
  { name: "Luka Modrić", team: "Croatia", source: "top100", bio: "This feels like it will be Modrić’s final major tournament for Croatia, but it feels unwise to count out the 40-year-old. After 13 years at Real Madrid, he moved to AC Milan before this past season and has not lost a step. Few players possess the control that Modrić has, and he can still boss a game as well as any midfielder in the world. Modrić’s 196 international appearances for Croatia rank third among players likely to play this summer, behind only Cristiano Ronaldo (226) and Lionel Messi (198)." },
  { name: "Moisés Caicedo", team: "Ecuador", source: "top100", bio: "While Chelsea has been hot and cold in recent years, Caicedo’s presence in midfield is immense. In his first three seasons for the Blues, he has made just shy of 150 appearances. He is a physical player who is not afraid of a tackle. Along with defenders Willian Pacho and Piero Hincapié, Caicedo is the main man in a strong center of an Ecuador team that could play spoiler this summer." },
  { name: "Pervis Estupiñán", team: "Ecuador", source: "top100", bio: "Estupiñán thrived in the Premier League for three seasons with Brighton before making a move to AC Milan last summer. He is one of the impressive talents that make Ecuador a potential sleeper this summer." },
  { name: "Willian Pacho", team: "Ecuador", source: "top100", bio: "Pacho broke out last season for PSG, cementing his spot in the middle of the French champions’ defense. From there, he starred en route to Champions League glory. He’ll partner Arsenal’s Piero Hincapíé in the middle of Ecuador’s back four, which on paper might be one of the stronger units in the field." },
  { name: "Mohamed Salah", team: "Egypt", source: "top100", bio: "Salah is lower on this list than he would have a couple of years ago. He is no longer in the conversation as one of the best players in the world, but he’ll still be the go-to guy for Egypt this summer." },
  { name: "Bukayo Saka", team: "England", source: "top100", bio: "Saka broke into the England team in 2021 and immediately made the right wing his position. The 24-year-old has 14 goals — three of which came at the 2022 World Cup — in 48 appearances for England and is a key player in the Three Lions’ attack. The fourth-highest ranked English player on this list, England will rely heavily on the left-footed Saka to create chances for goalscorer extraordinaire Harry Kane." },
  { name: "Cole Palmer", team: "England", source: "top100", bio: "Palmer joined Chelsea in 2023, and he will enter the World Cup in maybe his worst form since that move. The England midfielder scored 37 Premier League goals in his first two seasons with the Blues, but injuries have halted his progression this year. Still, we know what he is capable of, as evidenced by his goal in the Euro 2024 final against Spain. Whether Palmer starts for England remains to be seen, but the left-footed playmaker is likely to play a key role for the Three Lions." },
  { name: "Declan Rice", team: "England", source: "top100", bio: "Rice is an all-action midfielder who covers every blade of grass whenever he’s on the field. He is England’s engine and one of the first names on the team sheet. Over the past five seasons (two with West Ham and the last three with Arsenal), Rice has played more than 250 games. He is the definition of a box-to-box midfielder who will play a big role in both attack and defense for manager Thomas Tuchel’s team. When England is playing, expect to see a lot of Rice." },
  { name: "Eberechi Eze", team: "England", source: "top100", bio: "Eze made a huge move to Arsenal last summer and immediately became a big part of Mikel Arteta's squad. He normally plays an attacking role, but he could push for the spot in England's midfield that is usually occupied by Real Madrid star Jude Bellingham." },
  { name: "Harry Kane", team: "England", source: "top100", bio: "Kane does not have the physical traits of Haaland. He is simply the most prolific goal-scorer in the world, though. The former Tottenham star just finished his third season with Bayern Munich and has 139 goals in 143 appearances. He also averaged 23.3 goals per season during his nine full-time campaigns for Spurs. Kane is England’s all-time-leading scorer with 78 goals, and he is 13 appearances shy of the all-time record for most appearances for the Three Lions. He consistently finds space in the opposition’s 18-yard box and usually makes teams pay when he does. England reached the semifinals " },
  { name: "Jude Bellingham", team: "England", source: "top100", bio: "Bellingham broke out as a 17-year-old at Borussia Dortmund before a 2023 move to Real Madrid, with which he won the Champions League in his first season. In his third season in Spain, the 22-year-old hasn’t reached the heights he did in his first two campaigns. He is a constant threat in the 18-yard box and has scored many big goals for England. Already with 46 appearances for the national team at his young age, Bellingham is the present and future for the Three Lions. Whether they’re able to bring the World Cup home this summer may depend on his form." },
  { name: "Marc Guéhi", team: "England", source: "top100", bio: "Guéhi was the captain for Crystal Palace last summer when the South London club won the FA Cup. He moved to Manchester City earlier this year and has immediately become a fixture in the reigning Premier League champion’s defense." },
  { name: "Phil Foden", team: "England", source: "top100", bio: "Foden was the Premier League Player of the Season in 2023-24, but he has not built off that honor. At 25 years old, he is yet to find his footing and establish a spot in the England team." },
  { name: "Reece James", team: "England", source: "top100", bio: "James will be an important player for England this summer with versatility to play either right back or midfield. Staying healthy has been James’ problem at Chelsea, although he has played in more than two dozen games in the Premier League this season." },
  { name: "Aurélien Tchouaméni", team: "France", source: "top100", bio: "If France wins the World Cup this summer, the victory will be powered by its star attackers. Tchouaméni will likely be the unsung hero in midfield, though. The Real Madrid man will be on the ball more than any other French player this summer, dictating where the ball goes in attack and breaking up the opposition’s attacks. Tchouaméni is one of the best midfielders in the world, and his job is to complement the tournament’s best attack." },
  { name: "Bradley Barcola", team: "France", source: "top100", bio: "Barcola is one of the hugely talented French attacking players who will be vying for a starting spot. At 22 years old, Barcola is one of the best young wingers in the world and plays at PSG, which won last season’s UEFA Champions League." },
  { name: "Désiré Doué", team: "France", source: "top100", bio: "Doué will turn 21 during the World Cup and is already one of the best wingers in the world. He scored in last year's Champions League Final, which PSG won, and quickly has become a major contender for minutes in France’s stacked attack. Kylian Mbappé, Ousmane Dembélé and Michael Olise all seemingly have spots filled. Doué and Cherki will be the key contenders to start alongside that trio." },
  { name: "Ibrahima Konaté", team: "France", source: "top100", bio: "Konaté ranks just higher than Saliba, who he’ll likely partner in the middle of the French defense this summer. He’s one of the most physically imposing defenders in the world at 6-foot-4, and he also has the pace to stay with any attacker in the tournament." },
  { name: "Jules Koundé", team: "France", source: "top100", bio: "Koundé will likely start at right back for the French, who are among the favorites this summer. He has made at least 40 appearances in each of the last four seasons for Barcelona." },
  { name: "Kylian Mbappé", team: "France", source: "top100", bio: "Mbappé has scored at least 39 goals in each of the last six seasons between Paris Saint-Germain and Real Madrid. His pace is what separates him from Kane, as the Frenchman has the ability to blow past any defender to create chances for himself. Mbappe’s coming-out party was in 2018, when he scored four goals (three in the knockout stage) en route to France’s World Cup triumph. Since then, though, he has not won a major trophy beyond Ligue 1 with PSG outside of the UEFA Nations League in 2021. Mbappé has been in the headlines recently as he ends a second straight trophy-less season with Real Ma" },
  { name: "Marcus Thuram", team: "France", source: "top100", bio: "Kylian Mbappé will likely lead France’s attack at the start of the tournament, but Thuram is a very good alternative. Son of former France star Lilian Thuram, Marcus has scored at least 12 Serie A goals in each of his first three seasons at Inter Milan." },
  { name: "Michael Olise", team: "France", source: "top100", bio: "Olise was known as a very good playmaker for Crystal Palace in the Premier League, but he has gone into a new stratosphere since moving to Bayern Munich in 2024. The London-born playmaker has 41 goals and 46 assists through his first two seasons with the German giants. In that time, he established himself as a key player for France. He has only made 15 appearances for Les Bleus, but he will be a key player on the right wing for manager Didier Deschamps with his silky smooth dribbling and elegant left foot. Speaking of that incredible French attack…" },
  { name: "Mike Maignan", team: "France", source: "top100", bio: "Hugo Lloris retired from international play after the 2022 World Cup, and Maignan stepped in and hasn’t given the job up. Maignan is one of the best shot-stopping goalkeepers in the world and is firmly entrenched as AC Milan’s starter. He will be one of the best last lines of defense for a French squad that will be one of the most talented in World Cup history." },
  { name: "N'Golo Kanté", team: "France", source: "top100", bio: "Kanté may not be the flashiest name on the French team sheet, but he is arguably its most indispensable asset. Now 35 and playing in Turkey, the veteran has defied age to prove he is still one of the best defensive midfielders in Europe. As a key architect of France's 2018 World Cup glory, the tireless midfielder has built a career on disrupting world-class attacks with a smile on his face." },
  { name: "Ousmane Dembélé", team: "France", source: "top100", bio: "Dembélé won the Ballon d’Or as the best player in the world in 2025 after winning the Champions League with PSG. He played center forward for the French titans during that run but will likely find himself on the wing during the World Cup. Dembélé played six injury-riddled seasons with Barcelona before moving to PSG in 2023 and has thrived as the star since Kylian Mbappé moved to Real Madrid. This summer, Dembélé will feature alongside Mbappé and Olise to create one of the best attacking trios international soccer has ever seen. We’ll find out whether France can turn that collection of talent i" },
  { name: "Rayan Cherki", team: "France", source: "top100", bio: "Cherki is finishing up his first season at Manchester City and has found his form since the calendar turned to 2026. He is a dynamic dribbler who’s very difficult to get the ball away from, and he’s scored some massive goals late in the season to show off his end product." },
  { name: "William Saliba", team: "France", source: "top100", bio: "Since beginning his Arsenal career in 2022, Saliba has become one of the best defenders in the world. He’s an impressive athlete who was part of the French team that made it to the 2022 World Cup final. He’ll be one of the first names on the team sheet for Les Bleus this summer." },
  { name: "Antonio Rüdiger", team: "Germany", source: "top100", bio: "Rüdiger moved to Real Madrid in 2022 and quickly established himself as one of the best center backs in the world. He’s on the back nine of his career at 33 years old, but he would start for every country in this tournament. At 6-foot-3, Rüdiger brings an impressive combination of size and athleticism to the table that is rarely matched." },
  { name: "Florian Wirtz", team: "Germany", source: "top100", bio: "Wirtz broke out during the 2023-24 season when he led Bayer Leverkusen to an upset victory in the German Bundesliga. He scored 34 goals in his final two seasons with Leverkusen before making a nine-figure move to Liverpool, where he has failed to reach the same heights. Still, Wirtz will be a crucial factor for Germany this summer, alongside Jamal Musiala. The two young playmakers will be the keys for Germany for the next decade, if everything goes to plan." },
  { name: "Jamal Musiala", team: "Germany", source: "top100", bio: "The 23-year-old suffered a fractured fibula during last summer’s FIFA Club World Cup and missed the rest of 2025. Since then, he has slowly returned to the form that makes him one of the world’s best playmakers. An elite dribbler, Musiala will be at the core of the German attack this summer. If he is playing well, expect Germany to become a contender for the title." },
  { name: "Joshua Kimmich", team: "Germany", source: "top100", bio: "Kimmich is approaching 500 career appearances for Bayern Munich and has already played 108 times for Germany. The 31-year-old is a born leader and will patrol the midfield this summer for the Germans. He doesn’t seem to ever stop running and can play all over the pitch. Teams that win big tournaments like the World Cup need versatile and driven players like Kimmich in their team." },
  { name: "Antoine Semenyo", team: "Ghana", source: "top100", bio: "Semenyo has been a revelation in the Premier League this season. The London-born winger scored 10 goals in 20 appearances for Bournemouth before moving to Manchester City in January. England would love to have Semenyo in the fold for this tournament, but he made his debut for Ghana in 2022. He has become one of the best wingers in the world this season and will be the driving force behind any success Ghana has this summer." },
  { name: "Kaoru Mitoma", team: "Japan", source: "top100", bio: "Mitoma is an exciting winger who broke out two years ago for Brighton. He scored the winning goal for Japan back on March 31 in a friendly against England and will be the key player in attack for his country this summer." },
  { name: "Raúl Jiménez", team: "Mexico", source: "top100", bio: "Jiménez is a fixture in the Fulham starting lineup and will be the main man for Mexico this summer. With 44 goals for El Tri, he’s two goals behind former striker Jared Borgetti for second most all time." },
  { name: "Achraf Hakimi", team: "Morocco", source: "top100", bio: "Another PSG player, Hakimi is the top-ranked defender on this list, although he’s not necessarily this high because of his defense. Born in Madrid to Moroccan parents, Hakimi went through the ranks at Real Madrid before making successful moves to Borussia Dortmund, Inter Milan and PSG. In the French capital, he has further established himself as a force on the right wing. Few players in world soccer can match his pace, and he has also proven to be a more-than-capable defender. Hakimi was one of the stars that led Morocco to the semifinals of the 2022 World Cup. Having already made 95 appearanc" },
  { name: "Cody Gakpo", team: "Netherlands", source: "top100", bio: "Gakpo will be the key player in the Netherlands’ attack this summer, especially with news that his Oranje teammate Xavi Simons tore his ACL late in the season for Tottenham. Gakpo has emerged as a key playmaker for Liverpool and can play anywhere in attack. He’ll need to be at his best wherever he plays if the Dutch are going to contend this summer." },
  { name: "Denzel Dumfries", team: "Netherlands", source: "top100", bio: "Dumfries has established himself as one of the best attacking fullbacks in the world over the past few years. The right back is a constant goal threat and will be a focal point for opposition looking to slow down the Dutch this summer. Look for him to play a key role on both ends of the pitch for the Netherlands." },
  { name: "Frenkie de Jong", team: "Netherlands", source: "top100", bio: "Any manager would love to have a player like de Jong in midfield. The Barcelona man controls play and is one of the best defensive midfielders in the world. The combination of de Jong and Liverpool’s Ryan Gravenberch will be one of the best midfield duos in the tournament." },
  { name: "Jeremie Frimpong", team: "Netherlands", source: "top100", bio: "Frimpong is listed as a defender, but he’s as important to the Dutch attack as he is to its defense. He has impressive pace and is a constant threat down the right wing when he’s on the pitch." },
  { name: "Ryan Gravenberch", team: "Netherlands", source: "top100", bio: "Gravenberch moved to Liverpool in 2023 after an uneventful season at Bayern Munich, and he has established himself as an elite defensive midfielder. He was a key player last season when Liverpool won the Premier League and has remained a fixture in the Reds’ midfield." },
  { name: "Tijjani Reijnders", team: "Netherlands", source: "top100", bio: "While de Jong and Gravenberch do the dirty work in the Dutch midfield, Reijnders will be pulling the strings. The Dutchman thrived at AC Milan before moving to Manchester City ahead of this past season. While he hasn’t maintained a consistent starting spot, he’s the kind of midfielder who can control the tempo of a game." },
  { name: "Virgil van Dijk", team: "Netherlands", source: "top100", bio: "The No. 2-ranked center back on this list has been the standard at the position since moving to Liverpool in 2018. At 6-foot-5, van Dijk has impressive pace to accompany his size, which means few attackers are able to dribble past him. He has won the Premier League, FA Cup and Champions League with Liverpool, but there’s no international glory to go along with that. The 34-year-old Dutch captain will be the driving force of his team’s defense this summer." },
  { name: "Erling Haaland", team: "Norway", source: "top100", bio: "Haaland is a 6-foot-5 monster whose pace and size are unmatched. He has scored more than 160 goals in his first four seasons with Manchester City, establishing himself as the best goal-scorer in the Premier League. He has been even more prolific for Norway with 55 goals in 49 appearances for the national team. Haaland has won the Premier League and Champions League, and he also has three Golden Boots as the Premier League’s top scorer on his resume. Next for him is success at the international level. This will be his first major tournament with Norway, which is potentially poised to break thro" },
  { name: "Martin Ødegaard", team: "Norway", source: "top100", bio: "Two years ago, Ødegaard was considered one of the top play-making midfielders in the world. His last two seasons at Arsenal have been ravaged by injuries, though, so he hasn’t been able to regain that form. He’ll be the key playmaker for Norway this summer with the goal of feeding strikers Erling Haaland and Alexander Sørloth." },
  { name: "Bernardo Silva", team: "Portugal", source: "top100", bio: "Silva is finishing his final season at Manchester City after nine years at the club that have seen him win everything. He has six Premier League winners medals to go with two FA Cup and five EFL Cup victories, as well as the 2023 Champions League. He’s as dependable a player as they come in midfield and, along with Bruno Fernandes, will orchestrate the Portuguese attack this summer to help complement Ronaldo." },
  { name: "Bruno Fernandes", team: "Portugal", source: "top100", bio: "Since moving to Manchester United in January 2020, Fernandes has been one of the best playmakers in the Premier League. He has made more than 300 appearances for the Red Devils in those six seasons. While Ronaldo will grab the headlines, the Portuguese attack will go through Fernandes. He has 19 assists in the Premier League this season, and he’s second in the Premier League in assists to only Mohamed Salah since arriving in England. Given his recent form, ability to create scoring chances and to score goals, Fernandes will be the star man for Portugal’s attack this summer." },
  { name: "Cristiano Ronaldo", team: "Portugal", source: "top100", bio: "This may seem low for Ronaldo, but it’s impressive for the 41-year-old goalscoring extraordinaire to still be competing at this level." },
  { name: "Gonçalo Ramos", team: "Portugal", source: "top100", bio: "Ramos famously replaced Cristiano Ronaldo in the Portugal lineup for a Round of 16 game against Switzerland at the 2022 World Cup and scored a hat trick. Ronaldo will likely start the tournament up front for Portugal, but Ramos is one of the best backup strikers you’ll see this summer." },
  { name: "João Cancelo", team: "Portugal", source: "top100", bio: "Few defenders will be important attackers for their countries this summer, but Cancelo is one of them. The right back has impressive pace that makes him a threat down the wing. He has 12 goals in 66 appearances for Portugal, which is a very good rate for a defender." },
  { name: "João Neves", team: "Portugal", source: "top100", bio: "As a 19-year-old, Neves played 55 games for Benfica in Portugal before making a move to PSG, with which he won the Champions League in his first season. At just 5-foot-9, Neves is not an imposing figure in midfield, but he controls the game as well as any player in the world. He is a menace defensively but can also drive the ball up field with it at his feet. He will partner PSG teammate Vitinha and veteran midfielders Bruno Fernandes and Bernardo Silva for a Portugal team that may boast the best midfield in the tournament." },
  { name: "Nuno Mendes", team: "Portugal", source: "top100", bio: "Mendes is the No. 2 left back on this list and No. 3 fullback. He joined PSG in 2021 and quickly established himself as an elite player at his position. Mendes is one of the fastest fullbacks in the world, and he’s also an extremely capable defender. With João Cancelo at right back and Mendes on the left, Portugal have one of the best fullback pairs in the tournament." },
  { name: "Rafael Leão", team: "Portugal", source: "top100", bio: "When Leão is fit and in form, few attackers in the world are better. Consistency has been the issue for the Portugal attacker, who has only scored five goals in 43 games for the national team. If he’s in form, Leão could be an X-factor capable of pushing Portugal over the top this summer." },
  { name: "Rúben Dias", team: "Portugal", source: "top100", bio: "Dias was the 2021 Premier League Player of the Season for Manchester City in his first year at the club. He is one of the most decorated defenders in the world. All that’s missing for the physical center back is success at the international level with Portugal. This summer will be a great chance for him to achieve that." },
  { name: "Vitinha", team: "Portugal", source: "top100", bio: "From a failed loan move to Wolverhampton Wanderers to one of the best players in the world, Vitinha is the top-ranked midfield player on this list. The Portuguese maestro played 19 Premier League games for Wolves during the 2020-21 season, but the club decided against making the move permanent. He returned to Porto and was sensational the following season before moving to PSG in 2022. Since then, he has become the best on-ball midfielder in the world. Last season, he became PSG’s motor en route to a Champions League title and has not slowed down since. Portugal’s midfield is stacked with Bruno" },
  { name: "Scott McTominay", team: "Scotland", source: "top100", bio: "McTominay went from Manchester United outcast to Napoli legend in his first season in Italy. He was the Serie A Player of the Season with Napoli winning the league in 2025. McTominay has also scored big goals for his country and will be Scotland’s key man in the middle this summer. If the Scots score a big goal or get a big result, chances are McTominay will be a big reason why." },
  { name: "Ismaïla Sarr", team: "Senegal", source: "top100", bio: "Sarr played all 38 games in the Premier League for Crystal Palace last season, during which the South London club also won the FA Cup. Sarr has made 83 appearances for Senegal and will be one of the go-to guys for his country this summer, alongside teammate Sadio Mané." },
  { name: "Sadio Mané", team: "Senegal", source: "top100", bio: "Mané just turned 34, so his best days might be behind him, but he could definitely still be an impact player this summer. He is Senegal’s all-time leading goalscorer, and he’s five appearances behind teammate Idrissa Gueye’s 131 for the most in the history of the national team." },
  { name: "Kim Min-jae", team: "South Korea", source: "top100", bio: "Kim won Serie A with Napoli in 2023 before making a big move to Bayern Munich. He hasn’t established himself as a first-choice player for the German giants, but he will be a pillar in the Korean defense this summer." },
  { name: "Son Heung-min", team: "South Korea", source: "top100", bio: "Son is in the middle of his first full season in Los Angeles after a decade in the Premier League with Tottenham Hotspur. He’s South Korea’s all-time leader in national team appearances." },
  { name: "Dani Olmo", team: "Spain", source: "top100", bio: "Olmo emerged as a key player for Spain at Euro 2024. He scored three goals — finishing in a six-way tie for the Golden Boot — including one in the quarterfinal and semifinal against Germany and France, respectively." },
  { name: "Fabián Ruiz", team: "Spain", source: "top100", bio: "Ruiz was part of PSG’s dominant midfield trio last year that powered the team’s Champions League victory. Spain’s midfield is loaded with talent, so it won’t be as easy for him to find a spot in the starting lineup." },
  { name: "Fermin López", team: "Spain", source: "top100", bio: "López is the perfect example of the impressive depth that Spain has in midfield. He has made more than 120 appearances for Barcelona over the past three seasons, but he might not come close to cracking the starting lineup. López is more than capable of scoring and creating goals and will be a key player for Spain this summer, regardless of whether he starts games." },
  { name: "Lamine Yamal", team: "Spain", source: "top100", bio: "Over the past three years, Yamal has taken over global soccer. He made his Barcelona debut as a 15-year-old in May 2023 and made his first start right after turning 16. Since then, he has made more than 150 appearances for Barcelona and 30 for Spain. He turned 17 during Euro 2024, during which he powered La Roja to win the tournament. Yamal suffered a hamstring injury in late April and faces a fitness race to ensure he’s healthy for the World Cup. When he’s fit, the young phenom will be on the right wing wreaking havoc on opposing defenses." },
  { name: "Marc Cucurella", team: "Spain", source: "top100", bio: "While players have come and gone at Chelsea over the past few years, Cucurella has been one constant presence. He’ll enter the World Cup having played more than 100 games over the past two seasons for the Blues, all since starting for Spain en route to the Euro 2024 crown two years ago." },
  { name: "Martín Zubimendi", team: "Spain", source: "top100", bio: "When Rodri got hurt in the first half of the Euro 2024 final against England, Zubimendi stepped in at halftime and helped lead Spain to victory." },
  { name: "Mikel Merino", team: "Spain", source: "top100", bio: "Merino is unlikely to start for Spain, but he'll still probably play a big role. He scored eight goals in 10 appearances last year for the reigning European champions. A midfielder by trade, Merino has also played as a striker for both club and country." },
  { name: "Mikel Oyarzabal", team: "Spain", source: "top100", bio: "A winger by trade for Real Sociedad, Oyarzabal has stepped up as a striker for the national team in the past. The best example was in the Euro 2024 final, when he scored the winning goal for Spain against England." },
  { name: "Nico Williams", team: "Spain", source: "top100", bio: "Williams was a star during Spain’s run two years ago at the Euros, but he hasn’t ascended at the club level since then. He has limitless potential and will be a key attacking option for Spain this summer. Whether he’s a starter or is doing so off the bench remains to be seen." },
  { name: "Pau Cubarsí", team: "Spain", source: "top100", bio: "Cubarsí turned 19 in January and has already played 125 times for Barcelona. He’s less established for Spain, having only made 11 appearances for the national team. There is a lot of competition for spots in the Spanish defense, and it would not surprise anyone if Cubarsí was in the lineup for the team’s World Cup opener against Cape Verde on June 15." },
  { name: "Pedri", team: "Spain", source: "top100", bio: "Pedri went from playing in Spain’s second division to making 52 appearances for Barcelona in 2020. Since then, he has become one of the best players in the world as a box-to-box midfielder for the Spanish giants. Pedri has already made 40 appearances for Spain at 24 years old, but he missed the run-in to the final of Euro 2024 after suffering a knee injury in the quarterfinal against Germany. When fit, Pedri is one of the first names on Spain’s formidable team sheet, which is especially impressive given the range of midfield depth that La Roja possess. When the reigning European champions are " },
  { name: "Rodri", team: "Spain", source: "top100", bio: "When Spain won Euro 2024, it was with Rodri pulling the strings in midfield. His performances that year with the national team and winning the Premier League with Manchester City saw him win the Ballon d’Or, which goes to the best player in the world for that season. Unfortunately, the past two seasons since that Euro triumph have been defined by injuries, with him playing just four games the following season while dealing with a knee injury. When he is fit, he is one of the first names on the team sheet for Spain. Rodri is one of the best midfielders in the world, dictating play on the ball w" },
  { name: "Alexander Isak", team: "Sweden", source: "top100", bio: "Isak scored 52 goals in his last two seasons at Newcastle before making a big-money move to Liverpool last summer. Injuries have limited him to just four goals and 21 games this season, but he is a constant threat to score whenever he’s on the pitch." },
  { name: "Viktor Gyökeres", team: "Sweden", source: "top100", bio: "Gyökeres scored a memorable hat trick against Poland in the UEFA World Cup playoffs in March, including one in the 87th minute to seal a 3-2 win. He moved to Arsenal last summer and has 18 goals in all competitions." },
  { name: "Arda Güler", team: "Turkey", source: "top100", bio: "Güler is finishing up his third season at Real Madrid and has emerged as a key player in the squad. He will be the main man for Türkiye for years to come, starting with this summer’s World Cup." },
  { name: "Kenan Yıldız", team: "Turkey", source: "top100", bio: "Yıldız broke into the Juventus lineup three years ago and quickly became a focal point of the team’s attack. At 20 years old, he has already made 28 appearances for Türkiye." },
  { name: "Alex Freeman", team: "United States", source: "usmnt-roster", bio: "Alex Freeman has been part of the U.S. senior team for barely a year. The 21-year-old fullback made his debut on June 7, 2025, in a friendly vs. Türkiye ahead of the Gold Cup. His performance throughout that summer’s tournament impressed Pochettino so much that he became a regular in the squad. Freeman was part of MLS club Orlando City from 2022-26 before making a big move to Europe and joining Villarreal earlier this year. While he hasn’t broken into the starting lineup on a regular basis, he did seek advice from Pochettino before moving overseas and decided this would be the best move for his career in the long run.", didYouKnow: "His father, Antonio Freeman, played wide receiver for the Green Bay Packers and helped the team win a Super Bowl. In retirement, he’s turned into his son’s No. 1 fan. \"When I was younger, I played all the sports and when it came time, I chose [soccer] and I feel like he was supporting me the whole time,\" the younger Freeman told me last June about choosing fútbol over football.", stat: "Freeman was named an MLS All-Star in 2025 and also selected as the MLS Young Player of the Year. — Litman" },
  { name: "Alex Zendejas", team: "United States", source: "usmnt-roster", bio: "", didYouKnow: "Zendejas grew up in El Paso, Texas, and represented the U.S. at youth level. In 2015, he was teammates with future national team mainstays Tyler Adams and Christian Pulisic at the CONCACAF U-17 Championship.", stat: "Zendejas was a Liga MX All-Star in 2025 and also named to the CONCACAF Champions Cup Best XI in 2024. He's won four Liga MX titles — three with América and one with bitter rivals Chivas. – McIntyre" },
  { name: "Antonee Jedi Robinson", team: "United States", source: "usmnt-roster", bio: "Robinson is one of the most important players on this U.S. team. He started every match of the 2022 World Cup, was considered the best left back in the Premier League last year and was voted U.S. Soccer’s Male Player of the Year in 2024. Robinson has experienced injuries and setbacks over the last year and told reporters in March that at one point he feared he wouldn’t make it back in time for this summer’s World Cup. But Robinson is fully fit and in form now for both club and country (see his strong goal against Germany, for example). And it’s a good thing, because as teammate Tim Ream said last camp, he’s \"extremely difficult to replace.\"", didYouKnow: "Robinson has gone by the nickname \"Jedi\" since he was a kid. The reason? He loved Star Wars and used to dress up as characters. The delightful moniker has stuck with him ever since.", stat: "Robinson was named the Fulham Player of the Season in the 2023-24 campaign and also was named the U.S. Soccer Player of the Year in 2025. — Litman" },
  { name: "Auston Trusty", team: "United States", source: "usmnt-roster", bio: "Timing can be everything when it comes to the World Cup. Take Trusty, who’s played in the Premier League and Champions League but who has made just eight U.S. appearances since his 2023 debut. He wasn’t even playing for Celtic midseason, but the left-footed defender — another Philadelphia Union product — impressed versus Portugal in March then helped the Hoops win the Scottish title on the final day of the season. In the end, that was enough to earn him one of Pochettino’s 26 golden tickets.", didYouKnow: "Trusty committed to playing for NCAA powerhouse University of North Carolina but elected to sign a homegrown contract with the Union instead. Before joining Celtic in 2023, he appeared in 33 Premier League matches for Sheffield United.", stat: "Trusty has won two Scottish Premiership titles with Celtic. — McIntyre" },
  { name: "Brenden Aaronson", team: "United States", source: "usmnt-roster", bio: "Brenden Aaronson broke through with the Philadelphia Union when he was only 18 years old, and the expectations for his career have been sky-high ever since. He played two seasons for the Union from 2019-2020, when he had seven goals and nine assists in 51 matches and helped the team win the 2020 Supporters Shield as the best regular-season MLS team. He joined Austrian club Red Bull Salzburg in January 2021. Then just 19 years old, Aaronson’s transfer fee was the highest for a U.S.-based homegrown player in MLS history. He scored nine goals and had nine assists in two seasons, before joining Premier League club Leeds United in 2022 on a $30 million transfer fee. He has made 57 appearances for the USA and scored nine goals and seven assists.", didYouKnow: "Back in the day, they used to call Aaronson the \"Medford Messi\" for his creativity, technical skill and attacking ability — along with his hometown. That nickname isn’t used much in the Premier League, but it was fun when he was first starting out in his pro career.", stat: "Aaronson has made more than 100 appearances combined in the Premier League and Bundesliga.", analyst: "Laken Litman" },
  { name: "Chris Brady", team: "United States", source: "usmnt-roster", bio: "Although he's made one senior international appearance, Brady is considered one of the country’s brightest goalkeeping prospects — potential that head U.S. goalkeeper coach Toni Jiménez and deputy Jack Robinson noticed shortly after joining the national team in late 2024. But that doesn't mean he’s inexperienced; a starter for the Fire at 19, Brady has already amassed more than 100 regular season MLS appearances.", didYouKnow: "He’s World Cup-bound now. But less than two years ago, Brady was unceremoniously cut from the U.S. team that competed at the 2024 Summer Olympics in Paris — a squad reserved almost exclusively for players 23 years old or younger, with just three overage spots permitted on the 18-man roster.", stat: "Brady recorded six clean sheets last season in MLS play. — McIntyre" },
  { name: "Chris Richards", team: "United States", source: "usmnt-roster", bio: "Despite a recent injury , the USA’s top defender will anchor the co-hosts’ backline during the tournament — Richards’ first after injury kept him off of then-coach Gregg Berhalter’s final 26-player list four years ago. The FC Dallas youth product, who made his professional debut with Bayern Munich in 2019, helped Palace win the 2025 FA Cup and reach the 2026 UEFA Conference League final.", didYouKnow: "The son of a former professional basketball player, Richards now stands 6-foot-2. That wasn’t always the case. \"I was probably 5-foot-5, 140 pounds, soaking wet until I was 16,\" he told me last October . That summer, I probably grew five to six inches and gained 40 pounds.\"", stat: "Chris Richards was named to the 2025 Gold Cup Best XI of the Tournament. He, alongside current U.S. teammate Matt Turner, joined former the legendary Tim Howard as only three USA players to be FA Cup winners. – McIntyre" },
  { name: "Christian Pulisic", team: "United States", source: "usmnt-roster", bio: "The U.S. men’s team’s undisputed headliner since he was a teenager, Christian Pulisic mostly lived up to the billing at the last World Cup in 2022, when his game-winning goal over Iran sent the Americans to the round of 16. Lightning quick, Hershey, Pennsylvania’s favorite son glides by the world’s best defenders and scores with ease when he’s at the height of his powers. But he had been struggling mightily heading into what should be a defining World Cup on home soil. The top scorer in the first half of Italy's Serie A season, Pulisic finished the campaign goalless since December, and finally broke his scoreless streak with the USMNT against Senegal on May 31. Fans of the home team are hoping that means the floodgates are finally open for the main event. So, for that matter, is Pulisic. \"", didYouKnow: "Pulisic’s father, Mark, was a professional indoor soccer player who played NCAA soccer at George Mason University, where he met Christian’s mom. Kelley Pulisic was a member of GMU’s women’s team. A diehard New York Jets fan, Christian watched Gang Green play in London in 2021, the same year he won the UEFA Champions League with Chelsea. He remains the only American ever to play in the final of Eur", stat: "His 33 goals are the fifth-most in U.S. men's national team history, and his 86 appearances are the most of any active player. — McIntyre" },
  { name: "Cristian Roldan", team: "United States", source: "usmnt-roster", bio: "Pochettino once told reporters that Christian Roldan is the \"perfect player\" because he \"has a little bit of everything.\" Asked why he thinks the U.S. coach views him that way, Roldan said he thinks it’s because he’s always ready. \"I got on the quickest flight, dropped whatever I was doing,\" Roldan said of when he was called in by Pochettino last fall. \"I take a lot of pride in what I do every day and so when my name was called upon, I was ready. And I think he appreciated that. It really meant the world, I think, to him staying ready even though my name wasn’t on a preliminary roster.\" \"It was my dream to make the World Cup,\" Roldan said in March. \"I have so much experience at the club level, and I was just ready for that opportunity to come. And whether it comes this World Cup or not, yo", didYouKnow: "Roldan was part of the 2022 World Cup roster, but didn’t play. He said it was a \"huge honor\" to be there, but it was difficult to watch from the bench.", stat: "Roldan has made 47 appearances for the national team. – Litman" },
  { name: "Folarin Balogun", team: "United States", source: "usmnt-roster", bio: "U.S. fans are counting on the New York-born, London-raised Folarin Balogun to score the bulk of the goals this summer. The hard-running striker found the net 18 times in 40 UEFA Champions League and Ligue 1 last season. Known as \"Balo,\" the Arsenal academy graduate excels at stretching defenses, combining with Pulisic and finishing with a precision that the U.S. squad has lacked historically. The soft-spoken forward is expected to spearhead the American attack when their World Cup campaign kicks off against Paraguay in Los Angeles on June 12. \"My mind naturally wanders to the opening game of the World Cup, and just the atmosphere,\" Balogun told me last September. \"It's almost like a freeze-frame, like a perfect image in my mind.\" It’s about to become reality.", didYouKnow: "Eligible to play for the U.S., England or Nigeria (homeland of his parents), Balogun represented the Three Lions at the youth national team level. Within the youth academies of England and Arsenal, Balogun played alongside midfielder Yunus Musah, who started each of the USA’s four games at the 2022 FIFA World Cup in Qatar.", stat: "Balogun scored in eight straight Ligue 1 matches for Monaco earlier this season, tying the all-time club record.", analyst: "Doug McIntyre" },
  { name: "Gio Reyna", team: "United States", source: "usmnt-roster", bio: "The silky smooth attacker and one-time teenage prodigy — Reyna turned 20 while the U.S. squad was preparing for its first game at the last World Cup in Qatar — has been beset by injury over the last four years. He’s featured sparingly at club level as a result, including this season. After leaving Borussia Dortmund last summer, he was limited to just four starts during this Bundesliga season. Reyna still managed to help the U.S. win CONCACAF Nations League titles in 2023 and 2024 and started all three games for the Stars and Stripes two years ago at Copa América. He also scored in his first match under Pochettino, a 2-1 win last November against Paraguay — the Americans’ opening opponent at this World Cup. \"Some people think that my dad made me a good player,\" Reyna told the Players Tribun", didYouKnow: "The son of two-time U.S. World Cup captain Claudio and former U.S. women’s national team winger Danielle Egan, Reyna credits his love of soccer to his older brother, Jack, who died of cancer at 13 in 2012.", stat: "Reyna has scored nine goals for the national team in 38 appearances. — McIntyre" },
  { name: "Haji Wright", team: "United States", source: "usmnt-roster", bio: "Haji Wright is a physically imposing player for the U.S. front line. At 6-foot-3, he’s dangerous in the box and a one-on-one threat. He’s scored 18 goals in 43 appearances for his club this season, and in February, he had a hat trick against Middlesbrough. Wright made his debut with the USA in June 2022, ahead of that summer's World Cup and scored in his first match on a penalty kick vs. Morocco. He’s recorded 20 appearances and scored seven international goals.", didYouKnow: "Wright was one of only three U.S. players to score a goal at the 2022 World Cup. Tim Weah scored in the first match, Christian Pulisic in the third, and then Wright had what everyone likes to describe as an accidental goal in the round of 16 match vs. the Netherlands when a cross from Pulisic ricocheted perfectly off his heel and into the back of the net.", stat: "In the past six seasons, Wright has scored more than 90 goals in his time in the Danish Superliga, Turkish league and English Championship. – Litman" },
  { name: "Joe Scally", team: "United States", source: "usmnt-roster", bio: "The versatile 23-year-old isn’t as attack-minded as the fleet-footed likes of Sergiño Dest, Alex Freeman or Tim Weah. But the stay-at-home defender gives Pochettino options. Although he’s naturally a right back, Scally has top-level experience as a left back, center back and even at defensive midfielder. Before moving overseas, the Long Island native played for MLS side NYCFC and was in the Pigeons’ academy with current club and U.S. teammate Gio Reyna.", didYouKnow: "In May, Scally became the youngest non-German player to play 150 games in the Bundesliga — all with ‘Gladbach. He was also the youngest member of the USA’s 2022 squad, at just 19.", stat: "Scally made 34 appearances for 'Gladbach last season. — McIntyre" },
  { name: "Malik Tillman", team: "United States", source: "usmnt-roster", bio: "It was almost exactly four years ago when Malik Tillman was officially cleared to represent the U.S. after FIFA approved his one-time switch from Germany. Tillman, whose mother is from Germany and father is from the U.S., grew up playing in the Bayern Munich academy. He debuted for the U.S. team on June 1, 2022, and has made 30 appearances since then. While he didn’t make the 2022 World Cup roster, he’s featured more with the team since Pochettino became manager and was on a hot streak last summer during the Gold Cup when he scored three goals.", didYouKnow: "Tillman played alongside U.S. teammate Chris Richards in the Bayern Munich academy. In addition, his brother, Timothy Tillman, has also represented the U.S. men's national team.", stat: "Tillman has recorded more than 50 goal contributions in the past three seasons for PSV and Bayer Leverkusen. — Litman" },
  { name: "Mark McKenzie", team: "United States", source: "usmnt-roster", bio: "The veteran center back is headed to his first career World Cup after being among the final cuts in 2022. Bronx-born but raised in Delaware, McKenzie played college soccer at Wake Forest before turning pro with the Philadelphia Union. He’s been in Europe since 2021, when he left the Union for Belgian club Genk, and made 28 starts in France’s Ligue 1 this year with Toulouse.", didYouKnow: "A forward as a youth, McKenzie grew up watching Arsenal and idolized French World Cup winner and current FOX Sports analyst Thierry Henry. \" Getting to meet him was really special,\" McKenzie told me in March. They met \"when he was coaching Montreal in 2020, my last season with the Union. I also met him unofficially at a New York Red Bulls game back when I was 12. Got a chance to get a shirt signed", stat: "McKenzie was named to the 2020 MLS Best XI prior to his move to Europe. — McIntyre" },
  { name: "Matt Freese", team: "United States", source: "usmnt-roster", bio: "This time a year ago, the Harvard graduate had never logged a minute for the senior U.S. national team. Fast-forward 12 months, and Freese will likely start for the Americans at soccer’s highest level. This remarkable ascent began with his star turn at last summer's CONCACAF Gold Cup, where \"Matty Ice\" prevailed in a penalty shootout over a Costa Rica squad led by Real Madrid legend Keylor Navas. He finished the year with 12 consecutive starts for his country and was superb in a pre-World Cup tune-up in March, despite a 2-0 loss to Portugal.", didYouKnow: "High achievement runs in his family. His father, Dr. Andrew Freese, who died of cancer in 2021, was a pioneering gene-therapy researcher who earned his PhD in neurobiology from MIT, while his grandfather, Jack Geary, was an AFL quarterback and Air Force pilot. Freese honors the latter by wearing No. 49 for NYCFC.", stat: "Freese was named a finalist for the 2025 MLS Goalkeeper of the Year award. — McIntyre" },
  { name: "Matt Turner", team: "United States", source: "usmnt-roster", bio: "Matt Turner started every match for the U.S. at the 2022 World Cup in Qatar. He remained the Americans’ No. 1 up until Matt Freese unseated him just before the 2025 Gold Cup. Turner, a resilient player who never gives up on anything, is still fighting to prove himself to U.S. manager Mauricio Pochettino and his staff. On the club front, Turner took a tour throughout several Premier League teams, playing for Arsenal, Nottingham Forest and Crystal Palace. He joined French club Lyon last summer, but was quickly loaned out to the Revs a couple months later, where he has been the starting goalkeeper ever since.", didYouKnow: "Turner didn’t even start playing soccer until he was a teenager. He ended up playing at Fairfield University, and while he wasn’t selected in the 2016 MLS Draft, he made an impression during a preseason trial with the Revs and shortly thereafter signed a contract with the club.", stat: "Turner has made 54 appearances for the national team, with 27 clean sheets. — Litman" },
  { name: "Max Arfsten", team: "United States", source: "usmnt-roster", bio: "Max Arfsten is another player who has made a lasting impression on Pochettino. The left back earned his first cap with the senior team in January 2025 and has made 20 appearances with one goal since then. Arfsten has had to rise quickly within the squad, earning playing time at left back while regular starter Antonee \"Jedi\" Robinson was out of the team due to injury. Arfsten has made the most of his opportunity and earned a spot on his first World Cup roster.", didYouKnow: "During the offseason, Arfsten partners with the gym Core 3 Method in his hometown of Fresno to play soccer with kids and adults with disabilities. \"I go there to give back to my community,\" Arfsten said in an interview with the local CBS outlet earlier this year. \"I’m a big advocate for giving back to my community where I’m from. It’s a pretty underserved community, and I enjoy using the platform", stat: "Arfsten was named an MLS All-Star in 2025, making 37 appearances and recording seven goals along with six assists. — Litman" },
  { name: "Miles Robinson", team: "United States", source: "usmnt-roster", bio: "The 6-foot-2 center back was projected as a possible starter before the last World Cup in Qatar, only to suffer an Achilles rupture ahead of the tournament. Four years on, Robinson is headed to his first World Cup. The fleet-footed former Syracuse University standout has made 40 international appearances for the Stars and Stripes, and he scored the extra-time goal in the 2021 CONCACAF Gold Cup final that won the U.S. the title over chief rival Mexico. Robinson also has won an MLS Cup, in 2018 with Atlanta United, where he spent seven seasons before signing with FCC two years ago as a free agent. Robinson is the highest paid defender in MLS at nearly $4 million, according to the MLS Players Association.", didYouKnow: "Named after Jazz legend Miles Davis, Robinson’s father, Jeff, is a professional musician.", stat: "Robinson has done lots of winning. He was on the American squads that hoisted the CONCACAF Nations League trophy in 2023 and 2024, and also claimed the Campeones Cup and U.S. Open Cup during his time with Atlanta. — McIntyre" },
  { name: "Ricardo Pepi", team: "United States", source: "usmnt-roster", bio: "Ricardo Pepi is fighting to be the team's go-to striker. He’s a proven scorer with his club, where he’s netted 19 goals across all competitions for PSV during the 2025-26 season. But he hasn’t quite had the same success with the national team, scoring a total of 13 goals in 37 appearances since he made his debut with the squad in 2021. Granted, he’s been passed over at times, like when former manager Gregg Berhalter decided not to take him to the 2022 World Cup. Those experiences have helped shape Pepi and have given him a chip on his shoulder. He’s anxious to perform for the U.S. this summer.", didYouKnow: "There have been rumors for months about Pepi potentially transferring from PSV to Premier League club Fulham. A previous deal collapsed in March, but there’s still a chance the clubs will reach an agreement in the future.", stat: "Pepi has scored more than 55 goals in league competition over the past four seasons. — Litman" },
  { name: "Sebastian Berhalter", team: "United States", source: "usmnt-roster", bio: "At first glance, you might just think of Sebastian Berhalter as former U.S. player and manager Gregg Berhalter’s son . But he’s made his own name quickly, especially when it comes to set pieces. Berhalter takes pinpoint corners and flawless free kicks. He laughs when people ask what the trick is to his service, but his answer is always the same. And it’s uncomplicated: He just works hard. Which makes sense for someone like Berhalter, who is so meticulous and particular when it comes to his preparation and routine. He was born in London when his father was a player for English club Crystal Palace. Sebastian was also part of the Columbus Crew academy, where Gregg was coach of the MLS club.", didYouKnow: "Four years ago, Sebastian was at the 2022 World Cup in the U.S. Soccer Friends and Family Program while his dad was coaching the team. Now, they’ve essentially swapped places with Sebastian on the field and his dad cheering in the stands.", stat: "Berhalter was named an MLS All-Star in 2025, making 47 appearances and scoring eight goals last season. – Litman" },
  { name: "Sergiño Dest", team: "United States", source: "usmnt-roster", bio: "One of the most skillful players in national team history, Dest is finally fully healthy after an ACL tear suffered just before the 2024 Copa América. In 2019, the two-footed fullback chose to play for the U.S. over the three-time World Cup runner-up Netherlands, where he was born and raised to a Dutch mom and American service member dad. Dest started Champions League games for Ajax as a teen, played with Lionel Messi at Barcelona and had a stint with seven-time European champ AC Milan before returning to the Eredivisie with PSV. He’s since won three straight league titles.", didYouKnow: "In an effort to recreate the streetball style he learned as a youth, Dest used his own money to build Sergiño Dest Court in his hometown of Almere. \"It's small, so you can go alone or with a couple friends, and you learn how to not just [boot] the ball forward and run. You have to control it in tight spaces,\" he told me of the idea behind the facility before it opened two years ago. \"I feel like s", stat: "Dest was named the U.S. Soccer Young Male Athlete of the Year in 2019 and was also named the Ajax Talent of the Year in 2020, also known as the Marco van Basten award. – McIntyre" },
  { name: "Tim Ream", team: "United States", source: "usmnt-roster", bio: "Tim Ream is the oldest player on the squad. The seasoned veteran started every match and played every minute at center back during the 2022 World Cup and has a glimmering club résumé that includes a nine-year period where he featured prominently at Fulham. He left the Premier League club as a legend, making 312 appearances for the Cottagers, which was more than any other player in the 21st century besides captain Tom Cairney. Ream is a tremendous asset for the U.S., where he takes on the role of a composed and reliable leader who serves as an anchor for a young group.", didYouKnow: "Pochettino named Ream as the U.S. captain this summer, putting him in a familiar spot. He’s worn the armband in nearly every match he’s played under this coaching staff.", stat: "In his career, Ream made 97 appearances in the Premier League and was named Player of the Year twice at Bolton and once at Fulham. — Litman" },
  { name: "Tim Weah", team: "United States", source: "usmnt-roster", bio: "Tim Weah has been a regular in the U.S. squad since his debut in 2018 when he was just 18 years old. Since then, he’s made 51 appearances and scored seven goals, including in the USA’s opening match of the 2022 World Cup when he found the back of the net in the first half against Wales. He has one of the most powerful shots on the team, is incredibly soft-spoken and humble, but also brings the vibes. If you’re wondering where the music is coming from in the locker room or on the team bus, you can usually find Weah holding the boombox.", didYouKnow: "Weah’s father, George Weah, was the top scorer in UEFA Champions League in 1995 and became the first African player to win the Ballon d’Or that same year. The elder Weah is also the former president of Liberia. But the one thing George was never able to do that Tim will now have done twice? Play in a World Cup.", stat: "During his time at Juventus, Weah made 78 appearances and recorded seven goals along with seven assists. – Litman" },
  { name: "Tyler Adams", team: "United States", source: "usmnt-roster", bio: "Tyler Adams is the heartbeat of this team. When he was just 23 years old, Adams captained the squad through the 2022 World Cup, and was always impressive during high-stakes moments during the tournament. Adams tells it like it is, be it in the press conference or in the locker room, and holds his teammates accountable. He’s relentless, demands the best from his team and is the squad's toughest player. He’s a pest on the field and does his damnedest to make it impossible for opponents to get by him and is always going to battle for 50–50 balls.", didYouKnow: "Adams has two sons under the age of three.", stat: "Adams was named U.S. Soccer Player of the Year in 2022 and has made more than 150 combined appearances in the Premier League and Bundesliga. – Litman" },
  { name: "Weston McKennie", team: "United States", source: "usmnt-roster", bio: "A starter in all four U.S. games at Qatar 2022, McKennie heads into his second World Cup as arguably America’s best soccer player, coming off a career-best season in Italy. The rangy Texan never stops running. His long throw-ins are de facto set plays, and he is especially adept at arriving as a late runner into the box and scoring; see his opener against Belgium in March or the nine he bagged in almost 40 games for Juventus in 2025-26.", didYouKnow: "The son of an Air Force officer, McKennie was born in Washington state and spent four years of his childhood living in Kaiserslautern, Germany, while his father was stationed at Ramstein Air Base nearby. He met U.S. legends Landon Donovan and Carlos Bocanegra there in 2006, when the American squad played a friendly there ahead of that year’s World Cup in Germany.", stat: "McKennie has made more than 220 appearances for Juventus since joining the club in 2020, with more than 50 goal contributions in that span. — McIntyre" },
  { name: "Federico Valverde", team: "Uruguay", source: "top100", bio: "Valverde has been an absolute machine for Real Madrid over the past four seasons, making at least 54 appearances in each campaign. Teams that win major trophies need a player like Valverde in midfield, as his motor will not stop over the course of the 90 minutes. He will do all the necessary dirty work while also contributing to his team’s attack. Uruguay is not among the favorites, but the two-time world champions will not be an easy out with Valverde leading the midfield." },
]

const BIO_ALIASES: Record<string, string> = {
  'antonee robinson': 'antonee jedi robinson',
}

const BIO_LOOKUP = new Map<string, FoxPlayerBioEntry>()
for (const entry of FOX_PLAYER_BIOS) {
  const key = normalizeFoxBioName(entry.name)
  BIO_LOOKUP.set(`${entry.team}|${key}`, entry)
  BIO_LOOKUP.set(key, entry)
}

export function normalizeFoxBioName(name: string): string {
  return name
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
}

export function getFoxPlayerBio(name: string, team: string): FoxPlayerBioEntry | undefined {
  const norm = normalizeFoxBioName(name)
  const alias = BIO_ALIASES[norm]
  return (
    BIO_LOOKUP.get(`${team}|${norm}`) ??
    BIO_LOOKUP.get(norm) ??
    (alias
      ? (BIO_LOOKUP.get(`${team}|${alias}`) ?? BIO_LOOKUP.get(alias))
      : undefined)
  )
}

export function getFoxPlayerBioMeta(name: string, team: string): {
  scoutBio?: string
  scoutBioSource?: string
  scoutBioAnalyst?: string
} {
  const hit = getFoxPlayerBio(name, team)
  if (!hit || hit.team !== team) return {}

  const parts = [hit.bio, hit.didYouKnow, hit.stat].filter(Boolean)
  if (parts.length === 0) return {}

  const source =
    hit.source === 'usmnt-roster'
      ? 'FOX Sports USMNT Roster (Jun 2026)'
      : 'FOX Sports Top 100 (Jun 2026)'

  return {
    scoutBio: parts.join(' ').slice(0, 1200),
    scoutBioSource: source,
    ...(hit.analyst ? { scoutBioAnalyst: hit.analyst } : {}),
  }
}
